B = {slug: {sec: (HEADS[slug][sec], TAILS[sec]) for sec in range(7)} for slug in HEADS}

def make_ad(heads, tails, r, nh=7, nt=7):
    hs = [heads[(r * 3 + i) % len(heads)] for i in range(nh)]
    ts = [tails[(r * 3 + i) % len(tails)] for i in range(nt)]
    return [f"{h} {t}" for h in hs for t in ts]

def emit_module(slug, round_idx):
    lines = ["# -*- coding: utf-8 -*-"]
    lines.append("AD = {")
    banks = B[slug]
    for sec in range(7):
        heads, tails = banks[sec]
        lines.append(" %d: %s," % (sec, repr(make_ad(heads, tails, round_idx, 7, 7))))
    lines.append("}")
    return "\n".join(lines)